 private static String str(Map<String,Object> r,String k){return Objects.toString(r.get(k));}private static String text(JsonNode n,String k){if(!n.required(k).isTextual())deny();return n.required(k).textValue();}private static void same(Object a,Object b){if(!Objects.equals(a,b))deny();}private static <T>T one(List<T> r){if(r.size()!=1||r.get(0)==null)deny();return r.get(0);}private static void deny(){throw new TenantAccessException(ErrorCode.ACCESS_DENIED);}
